import { radiantView } from './radiant-descent.js';
import { renderSpatialCommit } from './spatial-controls.js';

export function renderRadiantPanel(s,ui) {
  const {e,selectedDungeonRoom=null}=ui;
  const v=radiantView(s);if(!v)return '';
  const ids=new Set(v.rooms.map(r=>r.id)),position=r=>[60+r.x*145,52+r.y*125];
  const lines=v.rooms.flatMap(r=>r.visited?r.neighbors.filter(id=>ids.has(id)&&(r.id<id||!v.rooms.find(n=>n.id===id).visited)).map(id=>{const a=position(r),b=position(v.rooms.find(n=>n.id===id));return `<path d="M${a.join(' ')}L${b.join(' ')}"/>`;}):[]).join('');
  const selected=v.rooms.find(r=>'radiant_'+r.id===selectedDungeonRoom);
  const label=(text,x,y)=>{const rows=[];for(const word of text.split(/\s+/)){if(rows.length&&rows.at(-1).length+word.length<22)rows[rows.length-1]+=' '+word;else rows.push(word);}return `<text x="${x}" y="${y+31}" text-anchor="middle">${rows.map((row,i)=>`<tspan x="${x}" dy="${i?12:0}">${e(row)}</tspan>`).join('')}</text>`;};
  const nodes=v.rooms.map(r=>{const [x,y]=position(r);return `<g class="radiant-room ${r.id===v.current?'current':''} ${r.resolved?'resolved':''} ${selected?.id===r.id?'selected':''}" data-op="dungeon-select" data-id="radiant_${r.id}" role="button" tabindex="0" aria-pressed="${(selected?.id??v.current)===r.id}" aria-describedby="spatial-map-help" aria-label="${e(r.label+(r.id===v.current?' · current room':''))}"><circle cx="${x}" cy="${y}" r="18"/><text x="${x}" y="${y+5}" text-anchor="middle">${r.id===v.current?'YOU':r.resolved?'✓':r.visited?'◇':'?'}</text>${label(r.label,x,y)}</g>`;}).join('');
  return `<section class="panel radiant-chart" data-radiant-chart><div class="section-heading"><div><span class="eyebrow">A RECORDED DESCENT</span><h2>Floor ${v.floor} · the routes you can see</h2></div><span class="badge">${v.provisions} rations</span></div><div class="radiant-purpose"><strong>${e(v.goal.title)}</strong><p class="small-copy">${e(v.goal.description)} Lead: floor ${v.goal.floor}. ${v.completed?'Completed proof is ready to bring outside.':`Completed proof pays ${v.goal.gold} gold and ${v.goal.exp} field experience on return.`}</p></div><div class="radiant-map-scroll"><svg viewBox="0 0 565 375" role="group" aria-label="Discovered descent routes"><rect width="565" height="375" fill="#b6b0a2"/><image href="./art/parchment-v22.png" width="565" height="375" opacity=".15"/><g class="radiant-edges">${lines}</g>${nodes}</svg></div><p id="spatial-map-help" class="small-copy">Click, Enter or Space to inspect. Choose Confirm to move, or double click an available neighboring doorway. Unseen rooms keep their contents hidden.</p>${selected?`<h2 id="spatial-selection-title" data-radiant-selection aria-describedby="spatial-selection-details">${e(selected.label)}</h2>${renderSpatialCommit(s,'dungeon',selectedDungeonRoom,[],ui)}`:''}<p class="small-copy">Provisions used: ${v.provisionsUsed}. A new lower floor, camp or peaceful field agreement costs 1 ration and one actual day. Previously provisioned floors cost no second ration; returning outside is free.</p></section>`;
}
